import java.util.Scanner;

public class Main {
    static final int N = 100;
    static final int D = 31;
    static final long MOD = 1000000007L;

    static int base_d, index;
    static int[] digits = new int[N];
    static long number;

    static class Matrix {
        long[][] matrix_data = new long[D + 1][D + 1];

        Matrix() {
            for (int i = 0; i <= base_d; i++) {
                for (int j = 0; j <= base_d; j++) {
                    matrix_data[i][j] = 0;
                }
            }
        }

        Matrix multiply(Matrix other) {
            Matrix result = new Matrix();
            for (int i = 0; i <= base_d; i++) {
                for (int j = 0; j <= base_d; j++) {
                    for (int k = 0; k <= base_d; k++) {
                        result.matrix_data[i][j] = (result.matrix_data[i][j] + this.matrix_data[i][k] * other.matrix_data[k][j]) % MOD;
                    }
                }
            }
            return result;
        }
    }

    static Matrix base_matrices[] = new Matrix[N];

    static Matrix rotate_matrix(int shift) {
        shift = (shift + base_d) % base_d;
        Matrix m = new Matrix();
        for (int i = 0; i < base_d; i++) {
            m.matrix_data[i][(i + shift) % base_d] = 1;
        }
        m.matrix_data[base_d][base_d] = 1;
        return m;
    }

    static void initialize() {
        base_matrices[0] = new Matrix();
        for (int i = 1; i < base_d; i++) {
            base_matrices[0].matrix_data[i][i] = 1;
        }
        base_matrices[0].matrix_data[base_d][0] = 1;
        base_matrices[0].matrix_data[base_d][base_d] = 2;
        base_matrices[0].matrix_data[0][base_d] = -1;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        number = sc.nextLong();
        base_d = sc.nextInt();

        index = 0;
        long tempNumber = number;
        while (tempNumber > 0) {
            digits[index] = (int)(tempNumber % base_d);
            tempNumber /= base_d;
            index++;
        }

        initialize();

        for (int i = 1; i < index; i++) {
            base_matrices[i] = rotate_matrix(0);
            for (int j = 0; j < base_d; j++) {
                base_matrices[i] = base_matrices[i].multiply(base_matrices[i - 1]).multiply(rotate_matrix(1));
            }
        }

        Matrix answer = rotate_matrix(0);
        for (int i = index - 1; i >= 0; i--) {
            for (int j = 0; j < digits[i]; j++) {
                answer = answer.multiply(base_matrices[i]).multiply(rotate_matrix(1));
            }
        }

        System.out.println((answer.matrix_data[base_d][base_d] + MOD) % MOD);
        sc.close();
    }
}
